import numpy as np
from PIL import Image
for st in ['initial','stage_14','stage_15','stage_16']:
 for cam in ['robot0_agentview_left','robot0_agentview_right','robot0_agentview_center']:
  a=np.array(Image.open(f'/app/output/{st}/last/{cam}.jpg')).astype(int)
  # orange/yellow mask, exclude bright white
  m=(a[:,:,0]>105)&(a[:,:,1]>65)&(a[:,:,0]-a[:,:,2]>45)&(a[:,:,1]>a[:,:,2]*1.35)
  # ROI in likely upper appliance region
  if cam.endswith('left'): roi=(slice(45,120),slice(170,230))
  elif cam.endswith('right'): roi=(slice(45,120),slice(115,165))
  else: roi=(slice(45,120),slice(125,190))
  mm=m[roi]; y,x=np.where(mm)
  if len(x): print(st,cam,'n',len(x),'centroid',round(x.mean()+roi[1].start,1),round(y.mean()+roi[0].start,1),'bbox',(x.min()+roi[1].start,y.min()+roi[0].start,x.max()+roi[1].start,y.max()+roi[0].start))
  else: print(st,cam,'none')
